// TH15 synthetic aliases (transcribe/th15/touhou-bullets.ecl), source color kept.
const TH15_STAR_R: int = 608;      // source type 16, etSprite(1,16,6)
const TH15_BIG_BALL2: int = 656;   // source type 19, etSprite(0,19,1)

const RING_BALL_COLOR: int = 6;
const BIG_BALL_COLOR: int = 1;

const TIME_LIMIT: int = 2944;      // 120 shell buffer + 2820 source timer + 4 startup margin
const OPENING_BUFFER: int = 120;

// Source big-ball EX chain: OFFSCREEN(120) -> WAIT(30) -> LASER(delete parent).
// Birth ANIM(1)/BRIGHT are omitted per policy; ANIM's position -= 4*velocity stays
// folded into the spawn distance of each shot (see boss3_at / boss3_at2).
xformdef BALL_LIFE {
    offscreen_keep(120);
    wait(30);
    set_life(1);
}

// Source EX LASER: infinite, sprite 38 / color 2, 0.9*640 judgement length,
// width 16 -> infinite half-height 4 -> target width 8, phases 30/30/30/30.
// Constant full width during the 30-frame expand phase is the accepted approximation.
async sub ball_laser() {
    wait(29);  // bullet task starts one frame late; laser at ball age 30 as source WAIT(30)
    _ = laser(2, $self_x, $self_y, aim_player(), 576fx, 8fx, 30, 60, 30);
}

// st05bs.ecl:399-433 Boss3_at. etAim(0,1) fixed-direction fan, N=4, one speed layer:
// F(4,i) = +d/2, -d/2, +3d/2, -3d/2 around alpha = -pi/2; d = %A starts 800deg, -10deg/wave.
// Speed %B starts 4.0, -0.4/wave; etDist(0,24) minus ANIM 4*velocity gives the spawn offset.
sub boss3_at() {
    var rank: int = global(GVAR_RANK);
    var waves: int = 6;
    if rank == RANK_EASY { waves = 3; }
    var a: int = 145636;   // 800deg in BAM (source 13.962634f radians)
    var b: fx = 4fx;
    var w: int = 0;
    while w < waves {
        var dist: fx = 24fx - 4fx * b;
        for k in 0..4 {
            var mag: int = (k / 2 * 2 + 1) * (a / 2);
            var off: int = mag;
            if k % 2 == 1 { off = 0 - mag; }
            var ang: angle = 270deg + (off as angle);
            _ = fire(TH15_BIG_BALL2, BIG_BALL_COLOR,
                     $self_x + dist * cos(ang), $self_y + dist * sin(ang),
                     b, ang, BALL_LIFE, ball_laser);
        }
        a = a - 1820;      // 10deg
        b = b - 0.4fx;
        wait(20);
        w = w + 1;
    }
    if rank == RANK_EASY { wait(60); }   // source !E tail wait(60)
}

// st05bs.ecl:435-483 Boss3_at2. etAim(1,0) aimed single shot per etOn:
// angle = aim_now + %A, %A = +-85.5deg + RANDF2*20deg, +-9deg per 1-frame step.
// Easy fires only the first sweep (second sweep still waits 20 frames).
async sub boss3_at2() {
    var rank: int = global(GVAR_RANK);
    var waves: int = 6;
    if rank == RANK_EASY { waves = 2; }
    var speed: fx = 1.5fx;
    if rank == RANK_HARD { speed = 2fx; }
    if rank == RANK_LUNATIC { speed = 3fx; }
    var dist: fx = 24fx - 4fx * speed;   // etDist(1,24) minus ANIM 4*velocity
    var w: int = 0;
    while w < waves {
        var u: fx = (rand(65536) - 32768) as fx / 32768;   // source %RANDF2
        var a: int = 15565 + ((3641fx * u) as int);         // 85.5deg +- 20deg, BAM
        for i in 0..20 {
            var aim: angle = aim_player();
            var ang: angle = aim + (a as angle);
            _ = fire(TH15_STAR_R, RING_BALL_COLOR,
                     $self_x + dist * cos(ang), $self_y + dist * sin(ang),
                     speed, ang, none, none);
            a = a - 1638;   // 9deg
            wait(1);
        }
        var u2: fx = (rand(65536) - 32768) as fx / 32768;  // sampled on every rank
        var c: int = -15565 + ((3641fx * u2) as int);
        for j in 0..20 {
            if rank != RANK_EASY {   // source !NHL etOn(1)
                var aim2: angle = aim_player();
                var ang2: angle = aim2 + (c as angle);
                _ = fire(TH15_STAR_R, RING_BALL_COLOR,
                         $self_x + dist * cos(ang2), $self_y + dist * sin(ang2),
                         speed, ang2, none, none);
            }
            c = c + 1638;   // 9deg
            wait(1);
        }
        w = w + 1;
    }
}

// st05bs.ecl:392 moveRand(60,4,1.9) under moveLimit(0,128,280,48).
// Reused verified recipe: one signed direction sample, mode0 speed 1.9*(1-k/60),
// inner quarter region x+-70 / y116..140, per-tick clamp x+-140 / y104..152.
sub move_rand_60() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 116fx {
        if a < 0 { a = -a; }
    } else if $self_y > 140fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    var dir: angle = a as angle;
    var dx: fx = cos(dir);
    var dy: fx = sin(dir);
    for k in 1..61 {
        var sp: fx = 1.9fx * ((60 - k) as fx) / 60fx;
        var nx: fx = $self_x + dx * sp;
        var ny: fx = $self_y + dy * sp;
        if nx < -140fx { nx = -140fx; }
        if nx > 140fx { nx = 140fx; }
        if ny < 104fx { ny = 104fx; }
        if ny > 152fx { ny = 152fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
}

// st05bs.ecl:331-397 Boss3 body. Entry state from st05bs.ecl:8-34:
// position (0,128), hurtbox 40 / hitbox 48 (circles via documented *0.5 branch).
// timerReset at :346 is the card's T0; prep movePosTime(60,4,0,128)+wait(120)+wait(60) = 180.
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);   // source movePosTime(60,4,0,128)
    wait(120);
    wait(60);
    loop {
        boss3_at();
        spawn boss3_at2();
        var rank: int = global(GVAR_RANK);
        var gap: int = 60;
        if rank == RANK_EASY || rank == RANK_NORMAL { gap = 80; }
        if rank == RANK_LUNATIC { gap = 40; }
        wait(gap);          // source wait([-1])
        move_rand_60();     // source moveRand(60,4,1.9) + wait(60)
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 16320, 0, 0, 0, source_enemy);   // source lifeSet(16320)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
